const sources=pdfs.map(p=>{const [title,author,date,url]=sourceMeta[p.id];return {id:p.id,url:url||pathToFileURL(p.file).href,title,author,publishedDate:date,retrievedAt:'2026-08-01T00:00:00+05:30',extractionMethod:'Local PDF: page-level pypdf layout extraction, link/metadata audit, embedded-image extraction',status:'complete',headingsFound:p.headings.length,codeBlocksFound:0,imagesFound:p.embeddedImages.filter(x=>x.localPath).length,wordCount:p.wordCount,coverageNotes:`All ${p.pages} PDF pages processed; ${p.wordCount} words and ${p.embeddedImages.filter(x=>x.localPath).length} candidate images extracted.`,limitations:['PDF text order and character encoding can differ from visual layout; normalized teaching uses verified page context.','Candidate image count includes repeated page graphics; only meaningful visuals are rendered.'],localRawFile:p.file,localNormalizedFile:p.extractedText,pages:p.pages,sha256:p.sha256};});
