const sourceMap={
 'src-ykdojo-repo':'pdf-ykdojo-repo','src-reddit-25-tips':'pdf-reddit-25','src-ruben-1800-hours':'pdf-ruben-27','src-linkedin-32-tips':'pdf-linkedin-32','src-anthropic-best-practices':'pdf-official-best-practices','src-creator-economy-20-tips':'pdf-official-best-practices','src-reddit-community-tips':'pdf-reddit-25','src-medium-skills':'pdf-claudemd-masterclass'
};
