const curriculum=read('curriculum.json');
const mk=(id,title,difficulty,topics,type,insightId,objective,simple,procedure,bad,good,exercise,success,question,options,answer,explanation)=>({id,title,difficulty,topics,type,insightIds:[insightId],objective,simple,procedure,bad,good,exercise,success,quiz:{question,options,answer,explanation}});
const newModules=[
 mk('lesson-agentic-harness','Harness engineering: from demo to dependable system',2,['harness','agentic','architecture'],'lesson','agentic-architecture','Identify every system surrounding the model.','A prompt is one component. A dependable agent also needs controlled context, tools, state, memory, evaluation, permissions, traces, retry rules, and stopping conditions.',['Draw the agent boundary and goal.','List context inputs and tools.','Choose durable state and memory.','Define evaluation and stop conditions.','Add permissions, tracing, and recovery.'],'Use a smart model and keep retrying until it works.','Design the complete loop: explicit state, typed tools, outcome evaluator, bounded retries, logs, and a human escalation path.','Draw a harness diagram for one automation you use.','Every arrow has an owner, observable output, and failure path.','What distinguishes a production harness from a demo?',['A longer system prompt','Explicit feedback, state, safety, and observability','More agents'],1,'Reliability comes from the surrounding system, not model capability alone.'),
 mk('lesson-state-memory','Context, state, and memory architecture',3,['context','state','memory'],'lesson','state-memory','Store the right information in the right place.','Context is ephemeral working input. State tracks workflow progress. Memory preserves selected facts or patterns across runs. Mixing them creates bloated prompts and stale truth.',['Classify each datum as context, state, memory, or source of truth.','Keep authoritative state outside chat.','Write memory only after validation.','Attach provenance and expiry.','Rehydrate a fresh context from minimal state.'],'Keep the full transcript forever so the agent remembers.','Store task status in structured JSON, validated conventions in a small memory file, and load only relevant source material into each iteration.','Classify ten pieces of session information into context/state/memory.','A fresh run resumes correctly without the previous transcript.','Where should “task 4 passed” live?',['Context only','Structured workflow state','Global CLAUDE.md'],1,'Progress is state, not a timeless instruction.'),
 mk('lesson-tool-design','Tool and interface design',3,['tools','mcp','cli','schemas'],'lesson','tool-design','Give agents narrow, predictable hands.','Tools should expose one coherent capability with explicit input, structured output, useful errors, and least privilege. CLI and MCP are delivery mechanisms, not goals.',['Start from the missing capability.','Prefer an established CLI or API.','Define input/output schemas.','Constrain authority and time.','Test success, failure, and adversarial inputs.'],'Give the agent a generic shell and tell it to be careful.','Expose a read-only get_ci_failure(run_id) operation returning job, step, excerpt, and source URL; keep retry and mutation outside it.','Redesign one broad tool as two narrow operations.','Invalid calls fail clearly and the tool cannot affect unrelated resources.','What is the first reason to add MCP?',['It is fashionable','A needed external capability lacks a better narrow interface','To make prompts longer'],1,'Choose integration by capability gap and permission boundary.'),
 mk('lesson-orchestration','Orchestration and multi-agent systems',3,['orchestration','multi-agent','parallel'],'workflow','orchestration','Coordinate work without multiplying confusion.','Orchestration is dependency management: who does what, in which order, with what handoff and integration gate. Multiple agents are useful only for separable work.',['Draw task dependencies.','Keep shared decisions with one owner.','Fan out independent read/review tasks.','Isolate writers in worktrees.','Validate outputs against contracts.','Integrate centrally.'],'Launch five agents on the same feature and merge what looks best.','One lead owns architecture; independent agents map security and tests; one isolated writer implements; the lead reconciles evidence and runs integration checks.','Turn a project into a dependency graph and label parallel nodes.','No overlapping write ownership; every handoff has a schema and acceptance check.','When should two agents work in parallel?',['When their work is independent and outputs can be integrated','Whenever both are available','When they edit the same file'],0,'Independence and explicit integration are the prerequisites.'),
 mk('lesson-guardrails-human','Guardrails, permissions, and human gates',3,['guardrails','permissions','human-in-loop'],'decision','guardrails-hitl','Place control at the point of consequence.','Guardrails encode prohibited behavior, permissions limit reachable actions, and human gates reserve consequential decisions. Each layer covers different failures.',['Inventory assets and side effects.','Classify actions by impact and reversibility.','Constrain filesystem/network/tool scope.','Automate safe reads and checks.','Require approval before irreversible or external actions.','Log overrides.'],'Ask for approval on everything—or skip all permissions.','Auto-run local tests in a sandbox, allow read-only issue lookup, and require approval for push, deploy, deletion, or sending messages.','Create a permission matrix for your workflow.','A mistaken instruction cannot reach secrets, unrelated files, or production.','Which action most clearly needs a human gate?',['Read a local source file','Run a unit test','Deploy to production'],2,'Deployment has external and potentially irreversible impact.'),
 mk('lesson-evals-observability','Evals, observability, and tracing',3,['evals','observability','tracing'],'lesson','evals-observability','Know whether the agent succeeded and why.','An eval scores outcomes against a dataset or rubric. Observability records the execution path—context, tool calls, state, retries, latency, cost, and overrides.',['Define representative tasks and expected outcomes.','Record tool/state transitions with correlation IDs.','Track quality, cost, latency, retries, and overrides.','Separate model failure from tool/data failure.','Regression-test changes to prompts, tools, or models.'],'It worked on my last prompt, so ship it.','Run a versioned task set, compare pass rate and cost, and inspect traces for regressions before rollout.','Design five eval cases including one adversarial failure.','A regression is reproducible and traceable to a component or step.','What does observability add beyond a pass/fail eval?',['The execution evidence explaining the outcome','A prettier prompt','Unlimited retries'],0,'Traces explain how and where an outcome was produced.'),
 mk('lesson-stopping-recovery','Stopping conditions, reflection, and recovery',3,['stopping','reflection','recovery'],'lesson','stopping-recovery','Ensure every loop can finish safely.','Reflection is useful only when it compares evidence with a rule. A loop needs verified success, terminal failure, time/cost/attempt budgets, and escalation exits.',['Define machine-checkable success.','Set maximum attempts, time, and cost.','Name terminal errors and forbidden actions.','Reflect against evidence after each iteration.','Escalate ambiguity rather than retrying it.','Preserve trace and partial state.'],'Keep trying until you are confident.','Exit on passing acceptance checks; stop after three failed attempts or budget; escalate permissions and ambiguous requirements to a person.','Write success and failure exits for one agent loop.','Every execution ends in verified success, explicit failure, or owned escalation.','What is a safe stopping design?',['Only a completion phrase','Success plus budgets, terminal failures, and escalation','No limit if tests exist'],1,'A phrase alone can be emitted falsely; independent checks and hard bounds are required.'),
 mk('lesson-ralph-loop','Ralph loops and overnight builds',4,['ralph','loop','autonomy'],'workflow','ralph-loop','Use file-based iteration without unbounded autonomy.','Ralph repeatedly works one atomic story, tests it, records progress, and continues. Its value is fresh context plus durable state—not blind repetition.',['Write and review a PRD.','Convert it to atomic stories with passes:false.','Define executable acceptance checks.','Work one story per iteration.','Update state and progress notes only after checks pass.','Stop on completion, budget, terminal error, or human gate.','Run inside an isolated environment.'],'Build my whole SaaS overnight. Say DONE when finished.','In a disposable worktree/container, implement the next failing story only; run named checks; set passes:true only when they pass; stop after 12 iterations or $X.','Design a three-story Ralph task file and hard-stop policy.','A false DONE cannot terminate the loop, and a bad trajectory cannot run indefinitely.','What makes a Ralph loop trustworthy?',['The word DONE','Atomic work, external checks, durable state, and hard limits','Many retries'],1,'Verification and boundaries—not persistence alone—make it useful.'),
 mk('lesson-claudemd-layers','CLAUDE.md hierarchy and progressive disclosure',3,['claude-md','hierarchy','monorepo'],'reference','claudemd-hierarchy','Build concise instructions that load at the correct scope.','A hierarchy lets global preferences, team rules, personal overrides, and subsystem guidance remain separate. The root is an index, not a warehouse.',['Start with observed repeated corrections.','Choose global, root, local, or child scope.','Keep core commands and non-obvious invariants concise.','Link detailed references progressively.','Use deterministic tools for style enforcement.','Review and prune on repository changes.'],'Put 200 rules, every directory description, lint style, and current task in the root file.','Root: commands and invariants. Child frontend file: UI-specific rules. Local file: personal setup. Hook: formatter enforcement. Handoff: current task state.','Refactor a bloated instruction file into four destinations.','Each rule loads only where relevant and measurably changes behavior.','Where should frontend-only exceptions live?',['Global CLAUDE.md','A scoped child CLAUDE.md','The current chat forever'],1,'Narrow scope reduces noise and unintended application.'),
 mk('lesson-hooks-subagents','Hooks, subagents, skills, and MCP together',4,['hooks','subagents','skills','mcp'],'decision','hooks-enforcement','Compose extension mechanisms by responsibility.','CLAUDE.md tells; hooks enforce deterministic events; skills package on-demand methods; subagents isolate cognition; MCP bridges external capabilities.',['Name the missing behavior.','Classify it as instruction, deterministic event, reusable method, isolated work, or external capability.','Choose one mechanism first.','Limit trigger and authority.','Test failure and uninstall paths.'],'Install a plugin bundle and place all instructions in CLAUDE.md.','Hook blocks secret access; skill describes security review; read-only subagent performs it; MCP retrieves issue context; root CLAUDE.md states when to use the workflow.','Map five recurring jobs to the smallest mechanism.','No mechanism duplicates another and each has a clear owner and permission boundary.','What should enforce formatting after every edit?',['A hook','A subagent','A longer CLAUDE.md paragraph'],0,'Formatting is deterministic event-driven work.'),
 mk('lesson-knowledge-graph','Graphify, Obsidian, and provenance-linked knowledge',4,['knowledge-graph','obsidian','research'],'workflow','knowledge-graph','Turn document collections into a reversible, sourced second brain.','A knowledge graph models ideas as nodes and relationships as edges. Obsidian makes them navigable, but usefulness depends on provenance and retrieval—not note volume.',['Start in an isolated vault or deletable folder.','Ingest an explicit source set.','Extract concepts and typed relationships.','Create one note per useful concept.','Backlink every note to source and location.','Enrich bare notes with sourced summaries.','Define review, retrieval, and refresh routines.','Merge into the main vault only after audit.'],'Generate 600 linked titles directly inside my main vault.','Build an isolated vault, preserve source documents, attach provenance to every node, sample-check edges, then import one removable folder.','Create a five-document mini graph with source backlinks.','Every claim is traceable and the entire import can be removed cleanly.','What prevents graph-based synthesis from becoming unsupported?',['More edges','Source provenance on nodes and claims','A bigger vault'],1,'Backlinks allow every synthesis to be checked against origin.'),
 mk('lesson-daily-interface','Daily Claude Code interface mastery',2,['statusline','voice','terminal','sessions'],'reference','daily-interface','Reduce friction in frequent interactions.','Status and context visibility prevent accidental branch/session mistakes; voice captures detailed intent; aliases, concise output, history search, and background work reduce repeated overhead.',['Learn essential slash commands and input editing.','Expose model, directory, branch, dirty state, and context usage.','Use voice for rich briefs, then review transcription.','Ask for compact file/log slices.','Name and search sessions.','Background only bounded long-running work.','Adopt one customization at a time.'],'Install every customization and patch before doing real work.','Track recurring friction for a week, then add the smallest alias/status/voice improvement and verify it saves time without adding risk.','Measure one repeated interaction and remove two unnecessary steps.','The improvement is used repeatedly and does not broaden authority.','Why customize the status line?',['Decoration','To expose branch, worktree, and context state before acting','To increase model intelligence'],1,'Visible state prevents coordination errors.'),
 mk('lesson-research-writing-devops','Research, writing, browser, and DevOps workflows',3,['research','writing','devops','browser'],'workflow','research-writing-devops','Use the terminal as a universal interface while preserving verification.','Claude Code can orchestrate search, files, Markdown, CI logs, browsers, APIs, and artifacts. The common pattern is durable input, established tools, and independent evidence.',['Save source material and URLs.','Choose the direct CLI/API/browser tool.','Ask for structured sourced output.','Keep writing in reviewable Markdown.','For CI, reproduce and inspect history/flakiness.','For UI, combine DOM/accessibility checks with screenshots.','Use draft PRs or artifacts as review gates.'],'Research this, fix CI, and publish the result.','Collect cited evidence, produce a Markdown draft, diagnose CI with focused logs and history, verify changes, then create a draft PR without pushing or publishing automatically.','Turn one research result into a cited Markdown note and a verified action plan.','Claims have sources; commands/results are recorded; external publication remains reviewed.','What is the safest publication workflow?',['Agent publishes directly','Durable draft, evidence review, then explicit approval','Trust a polished tone'],1,'A reviewable artifact separates generation from external action.')
];
const expertPhase=curriculum.phases.find(p=>p.id==='phase-expert');
const advancedPhase=curriculum.phases.find(p=>p.id==='phase-advanced');
const productivePhase=curriculum.phases.find(p=>p.id==='phase-productive');
for(const m of newModules){const target=m.difficulty===2?productivePhase:m.difficulty===3?advancedPhase:expertPhase;const mods=target.levels[0].modules;if(!mods.some(x=>x.id===m.id))mods.push(m);}
write('curriculum.json',curriculum);

